import { ChangeDetectionStrategy, Component, computed, input } from '@angular/core';
import { toObservable, toSignal } from '@angular/core/rxjs-interop';
import { FormControl, ReactiveFormsModule } from '@angular/forms';
import { startWith, switchMap } from 'rxjs';
import { SelectFieldComponent } from '../../../../shared/ui/select-field/select-field.component';
import { FormFieldDescriptor } from '../../data/form-field.model';
import { FieldValue } from '../../validation/validation.model';

/** DOM id of the focusable control of a field (also used to focus the first invalid one). */
export function fieldInputId(key: string): string {
  return `field-${key}`;
}

@Component({
  selector: 'app-form-field',
  imports: [ReactiveFormsModule, SelectFieldComponent],
  changeDetection: ChangeDetectionStrategy.OnPush,
  styleUrl: './form-field.component.scss',
  template: `
    <div class="form-field" [class.form-field--invalid]="showError()">
      @if (field().type === 'checkbox') {
        <div class="form-field__check">
          <input
            class="form-field__checkbox"
            type="checkbox"
            [id]="inputId()"
            [formControl]="control()"
            [attr.required]="field().required ? '' : null"
            [attr.aria-required]="field().required ? 'true' : null"
            [attr.aria-invalid]="showError() ? 'true' : null"
            [attr.aria-describedby]="describedBy()"
          />
          <label class="form-field__check-label" [for]="inputId()"
            >{{ field().label }}@if (field().required) {
              <span class="form-field__star" aria-hidden="true"> *</span>
            }</label
          >
        </div>
      } @else {
        <label class="form-field__label" [for]="inputId()"
          >{{ field().label }}@if (field().required) {
            <span class="form-field__star" aria-hidden="true"> *</span>
          }</label
        >
        @if (field().type === 'select') {
          <app-select-field
            [inputId]="inputId()"
            [options]="field().options"
            [placeholder]="field().placeholder ?? 'Selecciona'"
            [invalid]="showError()"
            [describedBy]="describedBy()"
            [required]="field().required"
            [formControl]="control()"
          />
        } @else if (field().type === 'date') {
          <input
            class="form-field__control"
            type="date"
            [id]="inputId()"
            [formControl]="control()"
            [attr.required]="field().required ? '' : null"
            [attr.aria-required]="field().required ? 'true' : null"
            [attr.aria-invalid]="showError() ? 'true' : null"
            [attr.aria-describedby]="describedBy()"
          />
        } @else {
          <input
            class="form-field__control"
            type="text"
            [attr.inputmode]="field().type === 'number' ? 'numeric' : null"
            [id]="inputId()"
            [formControl]="control()"
            [placeholder]="field().placeholder ?? ''"
            [attr.required]="field().required ? '' : null"
            [attr.aria-required]="field().required ? 'true' : null"
            [attr.aria-invalid]="showError() ? 'true' : null"
            [attr.aria-describedby]="describedBy()"
          />
        }
      }
      @if (field().helpText) {
        <p class="form-field__help" [id]="helpId()">{{ field().helpText }}</p>
      }
      @if (showError()) {
        <p class="form-field__error" role="alert" [id]="errorId()">
          <svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true" focusable="false">
            <circle cx="8" cy="8" r="7" fill="none" stroke="currentColor" stroke-width="1.5" />
            <path d="M8 4.5v4.2M8 11v.5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" />
          </svg>
          <span>{{ field().errorMessage }}</span>
        </p>
      }
    </div>
  `,
})
export class FormFieldComponent {
  readonly field = input.required<FormFieldDescriptor>();
  readonly control = input.required<FormControl<FieldValue>>();
  readonly submitted = input(false);

  /** Re-evaluates whenever the control is touched or its status changes (OnPush + reactive forms). */
  private readonly tick = toSignal(
    toObservable(this.control).pipe(
      switchMap((control) => control.events.pipe(startWith(null))),
    ),
    { initialValue: null },
  );

  protected readonly inputId = computed(() => fieldInputId(this.field().key));
  protected readonly helpId = computed(() => `${this.inputId()}-help`);
  protected readonly errorId = computed(() => `${this.inputId()}-error`);

  protected readonly showError = computed(() => {
    this.tick();
    const control = this.control();
    return control.invalid && (control.touched || this.submitted());
  });

  protected readonly describedBy = computed(() => {
    const ids: string[] = [];
    if (this.field().helpText) ids.push(this.helpId());
    if (this.showError()) ids.push(this.errorId());
    return ids.length ? ids.join(' ') : null;
  });
}
import {
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  computed,
  forwardRef,
  inject,
  input,
  signal,
} from '@angular/core';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';

export interface SelectOption {
  label: string;
  value: string;
}

@Component({
  selector: 'app-select-field',
  changeDetection: ChangeDetectionStrategy.OnPush,
  styleUrl: './select-field.component.scss',
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => SelectFieldComponent),
      multi: true,
    },
  ],
  host: {
    '(document:click)': 'onDocumentClick($event)',
  },
  template: `
    <div class="select-field" [class.select-field--open]="open()">
      <button
        type="button"
        class="select-field__trigger"
        [class.select-field__trigger--invalid]="invalid()"
        role="combobox"
        aria-haspopup="listbox"
        [id]="inputId()"
        [disabled]="isDisabled()"
        [attr.aria-expanded]="open()"
        [attr.aria-controls]="listboxId()"
        [attr.aria-activedescendant]="open() ? optionId(activeIndex()) : null"
        [attr.aria-invalid]="invalid() ? 'true' : null"
        [attr.aria-required]="required() ? 'true' : null"
        [attr.aria-describedby]="describedBy()"
        (click)="toggle()"
        (keydown)="onKeydown($event)"
        (blur)="onBlur()"
      >
        <span
          class="select-field__value"
          [class.select-field__value--placeholder]="!selectedOption()"
          >{{ displayText() }}</span
        >
        <svg
          class="select-field__chevron"
          viewBox="0 0 16 16"
          width="16"
          height="16"
          aria-hidden="true"
          focusable="false"
        >
          <path
            d="M3.5 6l4.5 4.5L12.5 6"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
            stroke-linecap="round"
            stroke-linejoin="round"
          />
        </svg>
      </button>
      @if (open()) {
        <ul
          class="select-field__listbox"
          role="listbox"
          [id]="listboxId()"
          (mousedown)="$event.preventDefault()"
        >
          @for (option of options(); track option.value; let i = $index) {
            <!-- Keyboard handled on the combobox trigger (aria-activedescendant pattern). -->
            <!-- eslint-disable-next-line @angular-eslint/template/click-events-have-key-events, @angular-eslint/template/interactive-supports-focus -->
            <li
              class="select-field__option"
              [class.select-field__option--active]="i === activeIndex()"
              [class.select-field__option--selected]="option.value === value()"
              role="option"
              [id]="optionId(i)"
              [attr.aria-selected]="option.value === value()"
              (click)="pick(i)"
              (mousemove)="activeIndex.set(i)"
            >
              <span>{{ option.label }}</span>
              @if (option.value === value()) {
                <svg
                  class="select-field__check"
                  viewBox="0 0 16 16"
                  width="16"
                  height="16"
                  aria-hidden="true"
                  focusable="false"
                >
                  <path
                    d="M3 8.5l3.2 3.2L13 4.8"
                    fill="none"
                    stroke="currentColor"
                    stroke-width="2"
                    stroke-linecap="round"
                    stroke-linejoin="round"
                  />
                </svg>
              }
            </li>
          }
        </ul>
      }
    </div>
  `,
})
export class SelectFieldComponent implements ControlValueAccessor {
  private readonly host = inject<ElementRef<HTMLElement>>(ElementRef);

  readonly inputId = input.required<string>();
  readonly options = input<SelectOption[]>([]);
  readonly placeholder = input('Selecciona');
  readonly invalid = input(false);
  readonly describedBy = input<string | null>(null);
  readonly required = input(false);

  protected readonly value = signal('');
  protected readonly open = signal(false);
  protected readonly activeIndex = signal(0);
  private readonly formDisabled = signal(false);

  protected readonly isDisabled = computed(
    () => this.formDisabled() || this.options().length === 0,
  );
  protected readonly listboxId = computed(() => `${this.inputId()}-listbox`);
  protected readonly selectedOption = computed(
    () => this.options().find((o) => o.value === this.value()) ?? null,
  );
  protected readonly displayText = computed(() => {
    if (this.options().length === 0) return 'Sin opciones disponibles';
    return this.selectedOption()?.label ?? this.placeholder();
  });

  private onChange: (value: string) => void = () => undefined;
  private onTouched: () => void = () => undefined;

  protected optionId(index: number): string {
    return `${this.inputId()}-option-${index}`;
  }

  writeValue(value: string | null): void {
    this.value.set(value ?? '');
  }

  registerOnChange(fn: (value: string) => void): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.formDisabled.set(isDisabled);
  }

  protected toggle(): void {
    if (this.open()) {
      this.close();
    } else {
      this.openList();
    }
  }

  private openList(): void {
    if (this.isDisabled()) return;
    const idx = this.options().findIndex((o) => o.value === this.value());
    this.activeIndex.set(idx >= 0 ? idx : 0);
    this.open.set(true);
  }

  private close(): void {
    this.open.set(false);
  }

  protected pick(index: number): void {
    const option = this.options()[index];
    if (!option) return;
    this.value.set(option.value);
    this.onChange(option.value);
    this.close();
  }

  protected onKeydown(event: KeyboardEvent): void {
    const count = this.options().length;
    if (count === 0) return;
    if (!this.open()) {
      if (['Enter', ' ', 'ArrowDown', 'ArrowUp'].includes(event.key)) {
        event.preventDefault();
        this.openList();
      }
      return;
    }
    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault();
        this.activeIndex.set((this.activeIndex() + 1) % count);
        break;
      case 'ArrowUp':
        event.preventDefault();
        this.activeIndex.set((this.activeIndex() - 1 + count) % count);
        break;
      case 'Home':
        event.preventDefault();
        this.activeIndex.set(0);
        break;
      case 'End':
        event.preventDefault();
        this.activeIndex.set(count - 1);
        break;
      case 'Enter':
      case ' ':
        event.preventDefault();
        this.pick(this.activeIndex());
        break;
      case 'Escape':
        event.preventDefault();
        this.close();
        break;
      case 'Tab':
        this.close();
        this.onTouched();
        break;
    }
  }

  protected onBlur(): void {
    if (!this.open()) this.onTouched();
  }

  protected onDocumentClick(event: Event): void {
    if (this.open() && !this.host.nativeElement.contains(event.target as Node)) {
      this.close();
      this.onTouched();
    }
  }
}
