.stepper {
  display: flex;
  align-items: flex-start;
  list-style: none;
  margin: 0;
  padding: 0;

  &__summary {
    margin: 0 0 var(--space-2);
    font-size: 14px;
    font-weight: 500;
    color: var(--color-text-muted);

    @media (min-width: 576px) {
      position: absolute;
      width: 1px;
      height: 1px;
      overflow: hidden;
      clip-path: inset(50%);
      white-space: nowrap;
      margin: 0;
    }
  }

  &__step {
    position: relative;
    flex: 1 1 0;
    display: none;
    flex-direction: column;
    align-items: center;
    gap: var(--space-2);
    text-align: center;
    color: var(--color-text-muted);

    &--current {
      display: flex;
    }

    @media (min-width: 576px) {
      display: flex;
    }

    &:not(:first-child)::before {
      content: '';
      position: absolute;
      top: 15px;
      right: calc(50% + 20px);
      left: calc(-50% + 20px);
      height: 2px;
      background: var(--color-border);
      display: none;

      @media (min-width: 576px) {
        display: block;
      }
    }

    &--done + &::before,
    &--done + &--current::before {
      background: var(--color-action);
    }
  }

  &__circle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    width: 32px;
    height: 32px;
    border-radius: 50%;
    background: var(--color-surface);
    box-shadow: inset 0 0 0 1.5px var(--color-border);
    color: var(--color-text-muted);
    font-size: 14px;
    font-weight: 700;
  }

  &__step--current &__circle,
  &__step--done &__circle {
    background: var(--color-surface-highlight);
    box-shadow: inset 0 0 0 2px var(--color-action);
    color: var(--color-brand);
  }

  &__label {
    font-size: 14px;
    font-weight: 500;
  }

  &__step--current &__label {
    font-weight: 700;
    color: var(--color-brand);
  }
}
